    for order in ['msb','lsb']:
        if order=='msb':
            s=bytes(((b>>bit)&1) for b in d)
        else:
            s=bytes(((b>>bit)&1) for b in d)
        # pack bits into bytes
        out=bytearray()
        for i in range(0,len(s)-7,8):
            v=0
            for j in range(8): v=(v<<1)|s[i+j]
            out.append(v)
        idx=bytes(out).find(target)
        if idx>=0: found.append((bit,order,idx))
